CREATE OR ALTER PROCEDURE dbo.ClaimJobs @QueueName nvarchar(50),@WorkerId nvarchar(150),@BatchSize int=5 AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @BatchSize NOT BETWEEN 1 AND 100 THROW 50010,'Invalid batch size.',1;WITH Candidates AS(SELECT TOP(@BatchSize) * FROM dbo.Jobs WITH(UPDLOCK,READPAST,ROWLOCK) WHERE QueueName=@QueueName AND Status IN(0,3) AND(NextAttemptAt IS NULL OR NextAttemptAt<=SYSUTCDATETIME()) AND ScheduledAt<=SYSUTCDATETIME() AND(LockedUntil IS NULL OR LockedUntil<SYSUTCDATETIME()) ORDER BY Priority DESC,CreatedAt ASC) UPDATE Candidates SET Status=1,LockedBy=@WorkerId,LockedUntil=DATEADD(SECOND,COALESCE((SELECT VisibilityTimeoutSeconds FROM dbo.JobQueues WHERE QueueName=@QueueName),60),SYSUTCDATETIME()),AttemptCount=AttemptCount+1,StartedAt=COALESCE(StartedAt,SYSUTCDATETIME()) OUTPUT INSERTED.*;END;
GO
CREATE OR ALTER PROCEDURE dbo.CompleteJob @JobId bigint,@WorkerId nvarchar(150) AS BEGIN SET NOCOUNT ON;UPDATE dbo.Jobs SET Status=2,CompletedAt=SYSUTCDATETIME(),LockedBy=NULL,LockedUntil=NULL,LastError=NULL WHERE JobId=@JobId AND Status=1 AND LockedBy=@WorkerId;IF @@ROWCOUNT=0 THROW 50011,'Job lease lost or not owned by worker.',1;END;
GO
CREATE OR ALTER PROCEDURE dbo.FailJob @JobId bigint,@WorkerId nvarchar(150),@Error nvarchar(2000),@RetryDelaySeconds int=30 AS BEGIN SET NOCOUNT ON;DECLARE @Attempt tinyint,@Max tinyint;SELECT @Attempt=AttemptCount,@Max=MaxAttempts FROM dbo.Jobs WITH(UPDLOCK,ROWLOCK) WHERE JobId=@JobId AND Status=1 AND LockedBy=@WorkerId;IF @Attempt IS NULL THROW 50012,'Job lease lost or not owned by worker.',1;UPDATE dbo.Jobs SET Status=CASE WHEN @Attempt>=@Max THEN 4 ELSE 3 END,NextAttemptAt=CASE WHEN @Attempt>=@Max THEN NULL ELSE DATEADD(SECOND,CASE WHEN @RetryDelaySeconds<1 THEN 1 WHEN @RetryDelaySeconds>3600 THEN 3600 ELSE @RetryDelaySeconds END,SYSUTCDATETIME()) END,LastError=LEFT(@Error,2000),LockedBy=NULL,LockedUntil=NULL,CompletedAt=CASE WHEN @Attempt>=@Max THEN SYSUTCDATETIME() ELSE NULL END WHERE JobId=@JobId;END;
GO
CREATE OR ALTER PROCEDURE dbo.RecoverExpiredJobs AS BEGIN SET NOCOUNT ON;UPDATE dbo.Jobs SET Status=CASE WHEN AttemptCount>=MaxAttempts THEN 4 ELSE 3 END,NextAttemptAt=CASE WHEN AttemptCount>=MaxAttempts THEN NULL ELSE SYSUTCDATETIME() END,LastError=COALESCE(LastError,N'Worker lease expired.'),LockedBy=NULL,LockedUntil=NULL,CompletedAt=CASE WHEN AttemptCount>=MaxAttempts THEN SYSUTCDATETIME() ELSE NULL END WHERE Status=1 AND LockedUntil<SYSUTCDATETIME();SELECT @@ROWCOUNT RecoveredCount;END;
GO
